SELECT id,delegator, delegatee, delegation_start_date, delegation_end_date,delegation_status, creation_date,reason_for_delegation,"delete",delegation_cmdb_id,
    CASE
        WHEN delegation_scope = 'Line_Manager' THEN '1'
        WHEN delegation_scope = 'BPO' THEN '2'
        WHEN delegation_scope = 'Lm+BPO' THEN '3'
        ELSE 'unknown'
    END AS delegation_scope
FROM delegation rm WHERE 1=1
AND rm.delete = 0







                    AND rm.delegatee = #{DelegationBean.delegatee}


                    AND rm.delegator = #{DelegationBean.delegator}


                    AND rm.delegatee = #{DelegationBean.delegatee} AND rm.delegator = #{DelegationBean.delegator}









                AND (rm.delegator = #{DelegationBean.currentUserItCode} or rm.delegatee = #{DelegationBean.currentUserItCode})



                    AND rm.delegator = #{DelegationBean.currentUserItCode} AND rm.delegatee = #{DelegationBean.delegatee}


                    AND rm.delegator = #{DelegationBean.delegator} AND rm.delegatee = #{DelegationBean.currentUserItCode}


                    AND rm.delegatee = #{DelegationBean.delegatee}


                    AND rm.delegator = #{DelegationBean.delegator}




                        AND rm.delegator = #{DelegationBean.currentUserItCode} AND rm.delegatee = #{DelegationBean.delegatee}


                        AND rm.delegator = #{DelegationBean.delegator} AND rm.delegatee = #{DelegationBean.currentUserItCode}


                        AND 1=2


                        AND 1=2






        AND 1=2


order by rm.creation_date desc

SELECT rm.* FROM delegation rm WHERE 1=1 AND rm.delegator IN
#{seq}
AND CURRENT_DATE >= delegation_start_date AND CURRENT_DATE <= delegation_end_date AND rm.delete = 0 ORDER BY rm.creation_date DESC

SELECT rm.* FROM delegation rm
WHERE rm.delegator = #{DelegationBean.delegator}
AND rm.delegatee = #{DelegationBean.delegatee}


        AND rm.delegation_scope = 'Line_Manager'


        AND rm.delegation_scope = 'BPO'


        AND rm.delegation_scope = 'Lm+BPO'


        AND 1=2


AND rm.delegation_start_date = #{DelegationBean.delegationStartDate}
AND rm.delegation_end_date = #{DelegationBean.delegationEndDate}
AND rm.delete = 0

SELECT d.delegatee as bpo, string_agg(DISTINCT a.email, ',') AS email FROM ad_tb_upp_nature_2 a INNER JOIN delegation d ON lower(a.user_name) = lower(d.delegatee) WHERE CURRENT_DATE >= d.delegation_start_date AND CURRENT_DATE <= d.delegation_end_date AND d.delete = 0 AND d.delegator IN
#{item.bpo}
GROUP BY d.delegatee;
